def scan(p):
    B0=np.column_stack([np.exp(-p[0]*x**2),(t**2/(1+p[1]*t**2))*v**3])
    Q,_=np.linalg.qr(B0); r0=y-Q@(Q.T@y); Mr=M-Q@(Q.T@M)
    nr=np.sum(Mr**2,0); good=np.where(nr>1e-8*np.sum(M**2,0))[0]
    Mo=Mr[:,good]; out=[]
    # pairs via Gram
    G=Mo.T@Mo; b=Mo.T@r0
    best=(1e18,None)
    for a in range(len(good)):
        # two-col solve for each j
        Gaa=G[a,a]; 
        j=np.arange(a+1,len(good))
        if len(j)==0: continue
        det=Gaa*G[j,j]-G[a,j]**2+1e-30
        ca=(G[j,j]*b[a]-G[a,j]*b[j])/det
        cj=(Gaa*b[j]-G[a,j]*b[a])/det
        e=np.sum(r0**2)-(ca*b[a]+cj*b[j])
        k=np.argmin(e)
        if e[k]<best[0]: best=(e[k],(good[a],good[j[k]]))
        out.append((e[k],good[a],good[j[k]]))
    out.sort()
    return best,out[:5]
